             '\n'
             'def decay_heat_fraction(t):\n'
             '    # 🔧 TODO-EXT-A: return  0.066 * ( t**(-0.2) - (t + T_op)**(-0.2) )\n'
             '    return None\n'
             '\n'
             '# self-check at 1 hour after shutdown:\n'
             'val = decay_heat_fraction(HOUR)\n'
